const http = require('node:http');
const fs = require('node:fs');
const { pipeline } = require('node:stream/promises');

// Bad: buffers the whole file per request
http.createServer(async (req, res) => {
  const data = await fs.promises.readFile('./big.log');
  res.end(data);
});

// Good: constant memory, first bytes go out immediately
http.createServer(async (req, res) => {
  res.setHeader('Content-Type', 'text/plain');
  try {
    await pipeline(fs.createReadStream('./big.log'), res);
  } catch (err) {
    // client went away or file error; pipeline already cleaned up
  }
});

