async function main() {
  const rl = readline.createInterface({
    input: fs.createReadStream(file),
    crlfDelay: Infinity,
  });
  let n = 0;
  let errors = 0;
  for await (const line of rl) {
    n++;
    if (line.startsWith('ERROR')) {
      errors++;
      console.log(`line ${n}: ${line}`);
    }
  }
  console.log(`${errors} errors in ${n} lines`);
  fs.unlinkSync(file);
}
