const http = require('node:http');
const fs = require('node:fs');
const { pipeline } = require('node:stream/promises');

http.createServer(async (req, res) => {
  if (req.method === 'GET' && req.url === '/report') {
    const file = './report.csv';
    const { size } = await fs.promises.stat(file);
    res.writeHead(200, {
      'Content-Type': 'text/csv',
      'Content-Length': size,
      'Content-Disposition': 'attachment; filename="report.csv"',
    });
    try {
      await pipeline(fs.createReadStream(file), res);
    } catch (err) {
      // client aborted or read failed; streams already destroyed
      req.log?.warn(err);
    }
  }
}).listen(3000);

const MAX = 100 * 1024 * 1024; // 100 MB

async function handleUpload(req, res) {
  let seen = 0;
  try {
    await pipeline(
      req,
      async function* limit(source) {
        for await (const chunk of source) {
          seen += chunk.length;
          if (seen > MAX) throw new Error('too large');
          yield chunk;
        }
      },
      fs.createWriteStream('/tmp/upload.bin'),
    );
    res.writeHead(201).end('ok');
  } catch (err) {
    await fs.promises.rm('/tmp/upload.bin', { force: true });
    res.writeHead(err.message === 'too large' ? 413 : 400).end();
  }
}

